/* From Uiverse.io by doniaskima - Tags: input, css input, cool input */
.__UIV_SCOPE__ .inputContainer {
  position: relative;
  margin-bottom: 20px;
}

.__UIV_SCOPE__ .customInput {
  width: 100%;
  padding: 12px;
  font-size: 16px;
  background-color: transparent;
  border: none;
  border-bottom: 2px solid #007bff;
  outline: none;
  transition: border-color 0.3s ease;
  color: #007bff;
}

.__UIV_SCOPE__ .customInput:focus,
.__UIV_SCOPE__ .customInput:not(:placeholder-shown) {
  border-color: #0056b3;
}

.__UIV_SCOPE__ .inputLabel {
  position: absolute;
  top: 0;
  left: 0;
  pointer-events: none;
  padding: 5px;
  font-size: 16px;
  color: #007bff;
  transition: transform 0.3s ease, color 0.3s ease;
}

.__UIV_SCOPE__ .customInput:focus + .inputLabel,
.__UIV_SCOPE__ .customInput:not(:placeholder-shown) + .inputLabel {
  transform: translateY(-100%) translateX(-5px) scale(0.8);
}

.__UIV_SCOPE__ .inputUnderline {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 2px;
  background-color: #007bff;
}
